from bench.macrophage_cell import MacrophageCell, MacrophageMode
import enum

class MockClaimType(enum.Enum):
    MATH = 1

class MockTool(enum.Enum):
    SYMPY = "sympy"

class MockTriaged:
    def __init__(self, claim_type):
        self.claim_type = claim_type

class MockVerdict:
    def __init__(self, tool, confidence):
        self.tool_used = tool
        self.confidence = confidence

def test_falsifier():
    cell = MacrophageCell(mode=MacrophageMode.SELF_CHECK)
    triaged = [MockTriaged(MockClaimType.MATH)]
    verdicts = [MockVerdict(MockTool.SYMPY, "0.9") for _ in range(6)]

    defect_present = False

    try:
        cell.observe(verdicts=verdicts, triaged=triaged)
    except AttributeError as e:
        if "'int' object has no attribute 'lower'" in str(e):
            defect_present = True

    cell2 = MacrophageCell(mode=MacrophageMode.PATROL)
    try:
        cell2.observe(verdicts=verdicts)
    except TypeError as e:
        if "unsupported operand type(s) for +" in str(e):
            defect_present = True

    if defect_present:
        print("FALSIFIED: Type safety crashes confirmed")
    else:
        summary = cell.observe(verdicts=verdicts, triaged=triaged)
        if any(a.category == "method_claim_mismatch" for a in summary.anomalies):
            print("FALSIFIED: Type safety crashes confirmed")

if __name__ == "__main__":
    test_falsifier()

